/// SMLib `my_test_analytic_curves`: 11 points along a line along z over [-1, 2] found again on it.
#[test]
fn cci_point_solve_line() {
    point_solve(&C {
        c: Curve::Line {
            o: P3::new(1.0, 0.0, 0.0),
            d: V3::z(),
        },
        t0: -1.0,
        t1: 2.0,
    })
    .unwrap();
}

/// SMLib `my_test_analytic_curves`: 11 points along a quarter circle of radius 0.5 in the xz plane found again on it.
#[test]
fn cci_point_solve_circle() {
    point_solve(&C {
        c: Curve::Circle {
            c: P3::new(1.0, 0.0, 0.0),
            x: V3::x(),
            y: V3::z(),
            r: 0.5,
        },
        t0: 0.0,
        t1: std::f64::consts::FRAC_PI_2,
    })
    .unwrap();
}

/// SMLib `my_test_analytic_curves`: 11 points along three quarters of a 1 × 0.5 ellipse in the xz plane found again on it.
#[test]
fn cci_point_solve_ellipse() {
    point_solve(&C {
        c: Curve::Ellipse {
            c: P3::new(1.0, 0.0, 0.0),
            x: V3::x(),
            y: V3::z(),
            a: 1.0,
            b: 0.5,
        },
        t0: 0.0,
        t1: 1.5 * std::f64::consts::PI,
    })
    .unwrap();
}
